// Input validation and preprocessing
const input = $input.first().json;

// Validate required fields
if (!input.task || typeof input.task !== 'string' || input.task.trim().length === 0) {
  return {
    json: {
      success: false,
      error: 'Invalid input: task is required and must be a non-empty string',
      agentType: 'browser',
      errorCode: 'INVALID_INPUT'
    }
  };
}

// Sanitize and prepare input
const sanitizedTask = input.task.trim().slice(0, 5000); // Limit task length

return {
  json: {
    task: sanitizedTask,
    sessionId: input.sessionId || $execution.id,
    startTime: Date.now(),
    metadata: {
      inputLength: sanitizedTask.length,
      executionId: $execution.id
    }
  }
};

// Format successful output with comprehensive metadata
const input = $('Validate Input').first().json;
const result = $input.first().json;

const executionTime = Date.now() - (input.startTime || Date.now());

// Extract structured data from agent output
let extractedData = {};
let screenshots = [];
let lastUrl = null;

try {
  // Try to parse structured output from agent
  if (result.output) {
    const jsonMatch = result.output.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      const parsed = JSON.parse(jsonMatch[0]);
      extractedData = parsed.data || parsed.extractedData || {};
      screenshots = parsed.screenshots || [];
      lastUrl = parsed.url || parsed.lastUrl || null;
    }
  }

  // Extract from intermediate steps
  if (result.intermediateSteps) {
    for (const step of result.intermediateSteps) {
      if (step.observation) {
        if (step.observation.screenshot) {
          screenshots.push(step.observation.screenshot);
        }
        if (step.observation.url) {
          lastUrl = step.observation.url;
        }
      }
    }
  }
} catch (e) {
  // Non-critical parsing error
}

return {
  json: {
    success: true,
    agentType: 'browser',
    output: result.output || 'Task completed',
    screenshots,
    extractedData,
    url: lastUrl,
    metadata: {
      executionTime,
      toolCalls: (result.intermediateSteps || []).length,
      executionId: input.metadata?.executionId
    }
  }
};

// Handle error output
const input = $input.first().json;

return {
  json: {
    success: false,
    agentType: 'browser',
    error: input.error || 'Validation failed',
    errorCode: input.errorCode || 'VALIDATION_ERROR',
    output: null,
    metadata: {
      executionId: $execution.id
    }
  }
};

// Merge success and error outputs
const items = $input.all();
return items;
